@import "@fontsource-variable/mona-sans/wdth.css";
@import "@fontsource-variable/saira/wdth.css";

/* Light (faithful): white paper, black ink. The pale grey is ink at ~10% (resting marques,
   hairlines, placeholders); the mid grey is for secondary footer labels. No accent colour. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0 0 0);
  --card: oklch(0.975 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0 0 0);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.29 0 0);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.925 0 0);
  --muted-foreground: oklch(0.66 0 0);
  --accent: oklch(0.95 0 0);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.55 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0 0 0 / 10%);
  --input: oklch(0 0 0 / 30%);
  --ring: oklch(0 0 0);
  --highlight: oklch(0.66 0 0);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.85 0 0);
  --chart-1: oklch(0 0 0);
  --chart-2: oklch(0.35 0 0);
  --chart-3: oklch(0.55 0 0);
  --chart-4: oklch(0.72 0 0);
  --chart-5: oklch(0.86 0 0);
  --sidebar: oklch(0.975 0 0);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0 0 0);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.95 0 0);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0 0 0 / 10%);
  --sidebar-ring: oklch(0 0 0);

  --typeface-body: "Mona Sans Variable", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --typeface-display: "Mona Sans Variable", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --typeface-mono: "Saira Variable", "Eurostile", "Bank Gothic", ui-sans-serif, sans-serif;
  --radius: 0.125rem;
  --page-width: 120rem;
  --page-gutter: 1.125rem;
  --section-y: 2rem;
}

/* From 1024px the gutter opens to 32px, as on the original's 12-column grid. */
@media (min-width: 64rem) {
  :root {
    --page-gutter: 2rem;
  }
}

/* Dark (sibling, and the original's black sections and charcoal pages): black paper, white
   ink, rgb 25 charcoal as the card, rgb 43 as the muted/chip grey. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.215 0 0);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.215 0 0);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(1 0 0);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.29 0 0);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.29 0 0);
  --muted-foreground: oklch(0.68 0 0);
  --accent: oklch(0.25 0 0);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.65 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 30%);
  --ring: oklch(1 0 0);
  --highlight: oklch(0.68 0 0);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.35 0 0);
  --chart-1: oklch(1 0 0);
  --chart-2: oklch(0.8 0 0);
  --chart-3: oklch(0.62 0 0);
  --chart-4: oklch(0.45 0 0);
  --chart-5: oklch(0.3 0 0);
  --sidebar: oklch(0.215 0 0);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(1 0 0);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.29 0 0);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 12%);
  --sidebar-ring: oklch(1 0 0);
}
